<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Requisition System</title><style>:root{--navy:#173351;--blue:#2468b0;--pale:#e8f1fc;--ink:#182b3c;--muted:#657487;--line:#dfe6ed;--bg:#f6f8fb;--green:#26885b;--red:#b6464a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Inter,system-ui,sans-serif}.shell{min-height:100vh;display:flex}.sidebar{width:258px;background:var(--navy);color:#dce9f5;padding:25px 16px;position:fixed;inset:0 auto 0 0}.brand{display:flex;gap:11px;align-items:center;color:white;line-height:1.05}.mark{display:grid;place-items:center;width:37px;height:37px;border-radius:10px;background:#4f8ed1;font-weight:800}.nav{display:grid;gap:5px;margin-top:36px}.nav div{padding:11px 12px;border-radius:8px;color:#c9d8e8}.nav .active{background:#ffffff20;color:#fff}.foot{position:absolute;bottom:26px;border-top:1px solid #ffffff25;padding:18px 8px;width:calc(100% - 32px);font-size:12px}.content{margin-left:258px;width:calc(100% - 258px)}.top{height:100px;background:white;border-bottom:1px solid var(--line);padding:20px 44px;display:flex;justify-content:space-between;align-items:center}.top p{color:var(--blue);font-size:11px;font-weight:800;letter-spacing:.1em;margin:0}.top h1{font-size:23px;margin:3px 0}.page{padding:38px 44px;max-width:1440px}.hero{background:linear-gradient(104deg,#dbeaf9,#f3f8fd);border:1px solid #cedfee;border-radius:14px;padding:28px 32px;display:flex;justify-content:space-between}.hero h2{margin:6px 0;font-size:27px}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:17px;margin:25px 0}.card{background:#fff;border:1px solid var(--line);box-shadow:0 8px 25px #122d4a14;border-radius:11px;padding:22px}.stat{font-size:29px;font-weight:800}.label{color:var(--blue);font-size:11px;font-weight:800;letter-spacing:.1em}.section-head{display:flex;justify-content:space-between;align-items:start}.section-head h2{margin:2px 0}.badge{border-radius:20px;background:var(--pale);color:var(--blue);padding:4px 9px;font-size:11px;font-weight:800}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}button,select{font:inherit;padding:9px 12px;border-radius:7px;border:1px solid #cfd9e3;background:#fff;cursor:pointer}button.primary{background:var(--blue);color:#fff;border-color:var(--blue)}button.danger{color:var(--red);border-color:#d08c90}table{width:100%;border-collapse:collapse;margin-top:12px}th{text-align:left;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#667789;padding:0 12px 12px;border-bottom:1px solid var(--line)}td{padding:15px 12px;border-bottom:1px solid #edf1f5}small{display:block;color:var(--muted)}@media(max-width:800px){.sidebar{width:72px}.brand span:last-child,.nav span,.foot{display:none}.content{margin-left:72px;width:calc(100% - 72px)}.top,.page{padding-left:28px;padding-right:28px}}@media(max-width:600px){.sidebar{display:none}.content{margin:0;width:100%}.top{height:auto;padding:16px 18px}.page{padding:24px 18px}.cards{grid-template-columns:1fr}.hero{display:block}.top h1{font-size:18px}}</style>@livewireStyles</head><body><div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">RS</span><span>Requisition<br><strong>System</strong></span></div><div class="nav"><div class="active">◈ <span>Dashboard</span></div><div>✓ <span>My work queue</span></div><div>▦ <span>Request history</span></div></div><div class="foot">Shared workflow portal<br><strong>School Board Operations</strong></div></aside><main class="content"><livewire:requisition-workbench /></main></div>@livewireScripts</body></html>
